contract InvMutTest {
    C c;
    CoolerFactory factory;
    constructor(C _c) { c = _c; factory = c.factory(); }

    // We will create a request from msg.sender==address(this) by calling c.requestLoan,
    // then call c.clearRequest from a different address (simulated by calling directly
    // since the checker runs with this contract as msg.sender). To model the lender being
    // msg.sender of clearRequest, we will call clearRequest from this contract as lender.
    // Inputs: amount, interest, loanToCollateral, duration, repayDirect, isCallback
    function run(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration,
        bool repayDirect,
        bool isCallback
    ) public payable {
        require(loanToCollateral != 0, "loanToCollateral!=0");
        // Ensure decimals call is safe by reading collateral decimals
        ERC20 coll = c.collateral();
        ERC20 debt = c.debt();

        // We need to have enough collateral and debt balances for transfers.
        // Since we cannot mint here, we only proceed when this contract already has
        // sufficient collateral and debt tokens according to the function inputs.
        // Query needed collateral for the request
        uint256 neededCollateral = c.collateralFor(amount, loanToCollateral);

        // Precondition: this contract must own at least neededCollateral of collateral,
        // and at least 'amount' of debt for the clearRequest to transfer debt.
        // The checker may satisfy these by supplying token balances to this test contract.
        require(coll.balanceOf(address(this)) >= neededCollateral, "not enough collateral");
        require(debt.balanceOf(address(this)) >= amount, "not enough debt");

        // Step 1: create a request as owner==address(this)
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        // Snapshot pre-balance of owner (this) for debt token to observe debt transfer
        uint256 ownerDebtBefore = debt.balanceOf(address(this));

        // Step 2: clear the request by calling clearRequest as lender (this contract)
        // clearRequest expects reqID, repayDirect, isCallback
        uint256 loanID = c.clearRequest(reqID, repayDirect, isCallback);

        // After clearing, the request should be inactive, and a loan should exist with lender==msg.sender
        C.Request memory reqAfter = c.getRequest(reqID);
        C.Loan memory loan = c.getLoan(loanID);

        // Debt should have been transferred from lender (msg.sender) to owner (which is address(this) in request creation)
        // In clearRequest, debt().safeTransferFrom(msg.sender, owner(), req.amount);
        // Since here msg.sender == address(this) (the lender) and owner() == address(this) (the requester), the net effect
        // is a transfer from this to this, so balances unchanged. But the general requirement we assert is that
        // loan.lender equals the caller who invoked clearRequest (address(this)) and the request is inactive.

        // Build the general invariant: the loan's lender equals msg.sender of clearRequest (which is address(this)),
        // the request was set inactive, and the loan.request.amount equals the original requested amount
        // and the loan.amount equals req.amount + interestFor(req.amount, req.interest, req.duration)
        uint256 computedInterest = c.interestFor(reqAfter.amount, reqAfter.interest, reqAfter.duration);

        assert(
            loan.lender == address(this)
            && reqAfter.active == false
            && loan.request.amount == reqAfter.amount
            && loan.amount == reqAfter.amount + computedInterest
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We create a request as this contract, then call clearRequest as the same address (this contract)
    // to act as lender; verify relationships between request and created loan.
    function run(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration,
        bool repayDirect,
        bool isCallback
    ) public payable {
        // require valid loanToCollateral to avoid division by zero in collateralFor
        require(loanToCollateral != 0, "loanToCollateral!=0");

        // Ensure this contract has enough collateral to fund requestLoan (checker may arrange token balances)
        // We may only call view functions inside require, that's allowed.
        ERC20 coll = c.collateral();
        ERC20 debt = c.debt();

        uint256 neededCollateral = c.collateralFor(amount, loanToCollateral);
        require(coll.balanceOf(address(this)) >= neededCollateral, "insufficient collateral balance for request");

        // Create the request as msg.sender == address(this)
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        // Now act as lender by calling clearRequest from this same contract.
        // Ensure lender (this) has enough debt tokens for clearRequest to transfer req.amount
        require(debt.balanceOf(address(this)) >= amount, "insufficient debt balance to clear request");

        uint256 loanID = c.clearRequest(reqID, repayDirect, isCallback);

        // Observe post-state via public getters
        C.Request memory reqAfter = c.getRequest(reqID);
        C.Loan memory loan = c.getLoan(loanID);

        // Compute expected interest via public function
        uint256 expectedInterest = c.interestFor(reqAfter.amount, reqAfter.interest, reqAfter.duration);

        // Assert the general rule: loan.lender equals caller (this contract), request inactive, loan.request.amount matches request amount,
        // and loan.amount == request.amount + computed interest
        assert(
            loan.lender == address(this)
            && reqAfter.active == false
            && loan.request.amount == reqAfter.amount
            && loan.amount == reqAfter.amount + expectedInterest
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function driving the property test.
    function run(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration
    ) public payable {
        // avoid division by zero in collateralFor
        require(loanToCollateral != 0, "loanToCollateral!=0");

        ERC20 coll = c.collateral();
        ERC20 debt = c.debt();

        // Ensure this contract has enough collateral to create the request
        uint256 neededCollateral = c.collateralFor(amount, loanToCollateral);
        require(coll.balanceOf(address(this)) >= neededCollateral, "insufficient collateral");

        // create a request; top-level state-changing call
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        // Ensure this contract (acting as lender) has enough debt tokens to clear the request
        require(debt.balanceOf(address(this)) >= amount, "insufficient debt to clear");

        // clear the request as the same address (this contract) acting as lender
        uint256 loanID = c.clearRequest(reqID, true, false);

        // Observe post-state via public getters (views allowed here)
        C.Request memory reqAfter = c.getRequest(reqID);
        C.Loan memory loan = c.getLoan(loanID);

        // The rule: loan.collateral equals collateralFor(req.amount, req.loanToCollateral) and request inactive
        uint256 expectedCollateral = c.collateralFor(reqAfter.amount, reqAfter.loanToCollateral);

        assert(
            reqAfter.active == false
            && loan.collateral == expectedCollateral
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function driving the property test.
    function run(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration
    ) public payable {
        // loanToCollateral must be non-zero to avoid division by zero in collateralFor
        require(loanToCollateral != 0, "loanToCollateral!=0");

        ERC20 coll = c.collateral();

        // compute required collateral and ensure this contract has enough to transfer in requestLoan
        uint256 requiredCollateral = c.collateralFor(amount, loanToCollateral);
        require(coll.balanceOf(address(this)) >= requiredCollateral, "insufficient collateral");

        // create a request; top-level state-changing call
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        // record balances before rescind
        uint256 balBefore = coll.balanceOf(address(this));

        // rescind the request as the owner (owner() is immutable args; this contract must be owner in test fixture)
        c.rescindRequest(reqID);

        // record balances after rescind
        uint256 balAfter = coll.balanceOf(address(this));

        // read request state
        C.Request memory reqAfter = c.getRequest(reqID);

        // The rule: rescindRequest should mark request inactive and return exactly the collateral computed by collateralFor
        assert(
            reqAfter.active == false
            && balAfter == balBefore + c.collateralFor(amount, loanToCollateral)
        );
    }

    receive() external payable {}
}

