contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need an ERC20 token to act as collateral. We will use the public collateral() getter
    // of the clone only after calling generateCooler in the factory when the clone was deployed.
    // However the problem environment deploys a fresh C and gives it here as _c, so we assume
    // c.collateral() is a valid ERC20 contract the test can interact with.

    // The test calls requestLoan and checks that if it didn't revert then:
    //  - requests[reqID] is active
    //  - request fields amount, interest, loanToCollateral, duration equal inputs
    //  - the contract's collateral token balance increased by collateralFor(amount, loanToCollateral)

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        require(loanToCollateral != 0, "loanToCollateral nonzero");
        // Prepare: read collateral token and contract balances before
        ERC20 coll = c.collateral();
        uint256 beforeBal = address(coll).balance;
        // Note: address(coll).balance is ETH balance; we want ERC20 balanceOf(c). Use public getter.
        uint256 beforeTokenBal = coll.balanceOf(address(c));

        bool reverted;
        uint256 reqID;
        // call must be a top-level statement; wrap in try/catch to capture revert
        try c.requestLoan(amount, interest, loanToCollateral, duration) returns (uint256 id) {
            reverted = false;
            reqID = id;
        } catch {
            reverted = true;
        }

        // Read observable state after call. It's allowed to call public view functions.
        bool active = false;
        uint256 gotAmount = 0;
        uint256 gotInterest = 0;
        uint256 gotLoanToCollateral = 0;
        uint256 gotDuration = 0;
        uint256 afterTokenBal = coll.balanceOf(address(c));

        if (!reverted) {
            C.Request memory req = c.getRequest(reqID);
            active = req.active;
            gotAmount = req.amount;
            gotInterest = req.interest;
            gotLoanToCollateral = req.loanToCollateral;
            gotDuration = req.duration;
        }

        // Compute expected collateral transfer (use public collateralFor view)
        uint256 expectedCollat = c.collateralFor(amount, loanToCollateral);

        // Assert general rule: if call succeeded then request at reqID matches inputs and is active
        // and the token balance of c increased by at least expectedCollat.
        assert(
            reverted || (
                active &&
                gotAmount == amount &&
                gotInterest == interest &&
                gotLoanToCollateral == loanToCollateral &&
                gotDuration == duration &&
                afterTokenBal >= beforeTokenBal + expectedCollat
            )
        );
    }

    receive() external payable {}
 }

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We observe behavior of clearRequest. Parameters:
    // reqID - which request index to clear (must exist), repayDirect and isCallback control the call.
    // We require that reqID refers to an existing active request by first creating a request via requestLoan.

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, bool repayDirect, bool isCallback) public payable {
        // Preconditions: loanToCollateral != 0 to avoid division by zero in collateralFor
        require(loanToCollateral != 0, "nonzero loanToCollateral");

        // Create a request as msg.sender (which is this contract). This is a state-changing call and must be top-level.
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        // Observe the request snapshot before clear. Use public getter.
        C.Request memory beforeReq = c.getRequest(reqID);

        // Observe debt token and owner balances before attempting clear.
        ERC20 debt = c.debt();
        address ownerAddr = c.owner();
        uint256 ownerBefore = debt.balanceOf(ownerAddr);
        uint256 callerBefore = debt.balanceOf(address(this));

        bool reverted;
        uint256 loanID;
        // Call clearRequest as this contract (msg.sender for clearRequest will be this contract). Must be top-level try/catch.
        try c.clearRequest(reqID, repayDirect, isCallback) returns (uint256 id) {
            reverted = false;
            loanID = id;
        } catch {
            reverted = true;
            loanID = type(uint256).max;
        }

        // After-call observations
        C.Request memory afterReq = c.getRequest(reqID);
        uint256 ownerAfter = debt.balanceOf(ownerAddr);
        uint256 callerAfter = debt.balanceOf(address(this));

        // If the call succeeded, the request stored in the created loan should equal the original request,
        // the original request should be marked inactive, and debt tokens equal to req.amount should have moved
        // from msg.sender (this contract) to owner() (observable via balances).

        bool postConditions;
        if (!reverted) {
            // retrieve the loan and its request
            C.Loan memory loan = c.getLoan(loanID);

            bool requestEqual = (
                loan.request.amount == beforeReq.amount &&
                loan.request.interest == beforeReq.interest &&
                loan.request.loanToCollateral == beforeReq.loanToCollateral &&
                loan.request.duration == beforeReq.duration
            );

            bool requestDeactivated = (afterReq.active == false);

            // debt transfer: owner balance increased by req.amount OR caller decreased by req.amount
            // (some ERC20s may charge fees; require at least owner increased by expected amount when possible)
            uint256 expected = beforeReq.amount;
            bool ownerIncreased = (ownerAfter >= ownerBefore && ownerAfter - ownerBefore == expected);
            bool callerDecreased = (callerBefore >= callerAfter && callerBefore - callerAfter == expected);

            postConditions = requestEqual && requestDeactivated && (ownerIncreased || callerDecreased);
        } else {
            postConditions = true; // if reverted, we assert nothing about state change
        }

        // Final general assertion: either the call reverted, or the post-conditions hold.
        assert(reverted || postConditions);
    }

    // receive to accept any ETH refunds if needed
    receive() external payable {}
 }

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that performs the test.
    // Params create a request first; then attempt to clear it. We assert a general invariant:
    // either the clearRequest call reverted, or it produced a loan whose .request equals the original
    // request and the original request is no longer active.
    function run(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration,
        bool repayDirect,
        bool isCallback
    ) public payable {
        // avoid division by zero in collateralFor
        require(loanToCollateral != 0);

        // Create a request as this contract (top-level state-changing call).
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        // Snapshot the request before clearing (view call allowed anywhere).
        C.Request memory beforeReq = c.getRequest(reqID);

        bool reverted;
        uint256 loanID;

        // Attempt to clear the request as this contract. Must be a top-level try/catch.
        try c.clearRequest(reqID, repayDirect, isCallback) returns (uint256 id) {
            reverted = false;
            loanID = id;
        } catch {
            reverted = true;
            loanID = type(uint256).max;
        }

        // Read the request after the call and, if not reverted, the created loan.
        C.Request memory afterReq = c.getRequest(reqID);
        C.Loan memory createdLoan = C.Loan({ request: C.Request({ amount: 0, interest: 0, loanToCollateral: 0, duration: 0, active: false }), amount: 0, unclaimed: 0, collateral: 0, expiry: 0, lender: address(0), repayDirect: false, callback: false });
        if (!reverted) {
            createdLoan = c.getLoan(loanID);
        }

        // General invariant: either the clearRequest call reverted OR
        // (1) the loan's stored request matches the original request fields and
        // (2) the original request is marked inactive after the call.
        assert(
            reverted || (
                createdLoan.request.amount == beforeReq.amount &&
                createdLoan.request.interest == beforeReq.interest &&
                createdLoan.request.loanToCollateral == beforeReq.loanToCollateral &&
                createdLoan.request.duration == beforeReq.duration &&
                afterReq.active == false
            )
        );
    }

    receive() external payable {}
}

