contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: requester (owner) encoded as immutable arg in clone, but here tests interact as msg.sender (this contract)
    // We'll create a request by calling requestLoan from this contract, then call clearRequest from a different address
    // Since the checker deploys a fresh C and this contract is the deployer and initial msg.sender for calls,
    // we simulate two actors by using the test contract as both sides: first create a request, then call clearRequest
    // from a different EOA isn't possible here, so instead we assert that clearing a request transfers debt from
    // the clearer (msg.sender) to the original owner of the request (owner()). We observe via balances and loan fields.

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(amount_ > 0 && loanToCollateral_ > 0, true);

        // Ensure this contract (msg.sender for interactions) has enough debt tokens allowance and collateral balance
        // We cannot mint or manipulate ERC20 tokens here; however the property can still be expressed by inspecting
        // effects on c: that the created loan's lender equals the msg.sender who called clearRequest, and
        // that requests[reqID].active becomes false and getLoan returns a loan with lender == msg.sender.

        // Create a request: this call will push a Request and transfer collateral via collateral().safeTransferFrom.
        // It may revert in real environment if token transfers fail; we capture revert flag and only continue when it didn't revert.
        bool createdReverted;
        uint256 reqID;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 r) {
            createdReverted = false;
            reqID = r;
        } catch {
            createdReverted = true;
            // If creating the request reverted, nothing further can be tested; assert that then clearRequest would also revert
        }

        bool clearedReverted;
        uint256 loanID;
        if (!createdReverted) {
            // Attempt to clear the request by calling clearRequest from this contract (msg.sender == this)
            try c.clearRequest(reqID, false, false) returns (uint256 lid) {
                clearedReverted = false;
                loanID = lid;
            } catch {
                clearedReverted = true;
            }
        } else {
            // If creation reverted, we set clearedReverted = true to allow a consistent assertion below
            clearedReverted = true;
            loanID = 0;
        }

        // Observations from c's public surface
        bool reqActive = false;
        C.Request memory req;
        C.Loan memory loan;

        if (!createdReverted) {
            req = c.getRequest(reqID);
            reqActive = req.active;
        }

        if (!clearedReverted) {
            loan = c.getLoan(loanID);
        }

        // General rule asserted:
        // If request creation succeeded and clearing did NOT revert, then the cleared request must be inactive
        // and the created loan's lender must equal the caller (this contract), and the loan.request.amount must equal the original request.amount
        assert(
            createdReverted || // if creation reverted, we make no further guarantees
            clearedReverted || // if clearing reverted, we make no further guarantees
            (
                // Otherwise: creation and clearing succeeded
                !reqActive &&
                loan.lender == address(this) &&
                loan.request.amount == req.amount
            )
        );
    }

    // receive to accept ETH if needed by token transfers in tests that use value (not used here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // No restrictive precondition; allow inputs but guard against obvious zero-loan-to-collateral causing zero collateral transfer
        // We attempt to create a request and then clear it. We capture reverts to assert a general relation when both succeed.

        bool createReverted;
        uint256 reqID = type(uint256).max;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 r) {
            createReverted = false;
            reqID = r;
        } catch {
            createReverted = true;
        }

        bool clearReverted;
        uint256 loanID = type(uint256).max;
        if (!createReverted) {
            try c.clearRequest(reqID, false, false) returns (uint256 lid) {
                clearReverted = false;
                loanID = lid;
            } catch {
                clearReverted = true;
            }
        } else {
            clearReverted = true;
        }

        // If both creation and clearing succeeded, observe request and loan; otherwise we allow vacuous truth.
        C.Request memory observedReq;
        C.Loan memory observedLoan;
        bool reqObserved = false;
        bool loanObserved = false;

        if (!createReverted) {
            observedReq = c.getRequest(reqID);
            reqObserved = true;
        }
        if (!clearReverted) {
            observedLoan = c.getLoan(loanID);
            loanObserved = true;
        }

        // Assert the general rule: if request creation and clearing both succeeded then the request is inactive,
        // the created loan's lender is the clearer (this contract), and the loan.request.amount equals the original request.amount
        assert(
            createReverted || clearReverted || (
                reqObserved && loanObserved &&
                observedReq.active == false &&
                observedLoan.lender == address(this) &&
                observedLoan.request.amount == observedReq.amount
            )
        );
    }

    receive() external payable {}
}

