contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function driving the property test
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // Attempt to create a request; top-level state-changing call with try/catch
