contract InvMutTest {
    C c;
    ERC20 collateralToken;

    constructor(C _c) { c = _c; collateralToken = c.collateral(); }

    // single public entry performing the property test
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // avoid division by zero in collateralFor
        require(loanToCollateral_ != 0);

        // observe number of requests before by reading requests array length via public getter pattern
        // C has public Request[] requests; solidity generates a getter requests(uint) but not length, so we derive length by probing until revert is impossible here.
        // Instead, use getRequest in a loop up to a reasonable bound to find current length. The checker runs once, so use gas-limited loop cap.
        uint256 beforeRequests = 0;
        // find length by attempting calls until a revert; but view getter getRequest will revert on out-of-bounds, so we probe.
        // cap to 50 to keep this bounded; fresh contract will be small.
        for (uint256 i = 0; i < 50; i++) {
            try c.getRequest(i) returns (C.Request memory) {
                beforeRequests = i + 1;
            } catch {
                break;
            }
        }

        // record collateral token balance of c before
        uint256 beforeBal = collateralToken.balanceOf(address(c));

        bool reverted;
        // call requestLoan as this contract
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If reverted: assert requests length and collateral balance unchanged
        if (reverted) {
            // recompute length
            uint256 afterRequests = 0;
            for (uint256 i = 0; i < 50; i++) {
                try c.getRequest(i) returns (C.Request memory) {
                    afterRequests = i + 1;
                } catch {
                    break;
                }
            }
            assert(afterRequests == beforeRequests && collateralToken.balanceOf(address(c)) == beforeBal);
            return;
        }

        // If succeeded: new request appended at index beforeRequests
        C.Request memory r = c.getRequest(beforeRequests);

        // compute expected collateral via public view
        uint256 expectedCollateral = c.collateralFor(amount_, loanToCollateral_);

        uint256 afterBal = collateralToken.balanceOf(address(c));

        // General rule: fields equal inputs, active true, and collateral balance increased by expectedCollateral
        assert(r.amount == amount_ && r.interest == interest_ && r.loanToCollateral == loanToCollateral_ && r.duration == duration_ && r.active == true && afterBal == beforeBal + expectedCollateral);
    }

    // accept any token-less ETH (not used but present)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    ERC20 debtToken;
    ERC20 collateralToken;

    constructor(C _c) {
        c = _c;
        debtToken = c.debt();
        collateralToken = c.collateral();
    }

    // Single public entry performing the property test
    // Params: loanID to target an existing loan (or out-of-bounds to cause revert), repaid amount to attempt
    function run(uint256 loanID_, uint256 repaid_) public payable {
        require(true);

        // Observe loan snapshot before: try to read loan; if out-of-bounds the call will revert and we treat as no-loan
        bool couldReadBefore = true;
        C.Loan memory loanBefore;
        try c.getLoan(loanID_) returns (C.Loan memory lb) {
            loanBefore = lb;
        } catch {
            couldReadBefore = false;
        }

        // Record balances of involved parties before the call
        uint256 debtBalCallerBefore = debtToken.balanceOf(address(this));
        uint256 debtBalContractBefore = debtToken.balanceOf(address(c));
        uint256 collBalOwnerBefore = collateralToken.balanceOf(loanBefore.lender);
        uint256 collBalContractBefore = collateralToken.balanceOf(address(c));

        bool reverted;
        uint256 decollateralizedReturned = 0;

        // Make the state-changing call as a top-level statement and catch revert
        try c.repayLoan(loanID_, repaid_) returns (uint256 dec) {
            reverted = false;
            decollateralizedReturned = dec;
        } catch {
            reverted = true;
        }

        // Read loan after (if exists) and balances after
        bool couldReadAfter = true;
        C.Loan memory loanAfter;
        try c.getLoan(loanID_) returns (C.Loan memory la) {
            loanAfter = la;
        } catch {
            couldReadAfter = false;
        }

        uint256 debtBalCallerAfter = debtToken.balanceOf(address(this));
        uint256 debtBalContractAfter = debtToken.balanceOf(address(c));
        uint256 collBalOwnerAfter = 0;
        uint256 collBalContractAfter = collateralToken.balanceOf(address(c));
        if (couldReadBefore) {
            collBalOwnerAfter = collateralToken.balanceOf(loanBefore.lender);
        }

        // General invariant to assert:
        // If there was no loan before, repay should revert (can't repay nonexistent loan). If loan existed:
        // - If call reverted: loan amount and loan.collateral unchanged and balances unchanged.
        // - If succeeded: decollateralizedReturned == floor(loanBefore.collateral * min(repaid_, loanBefore.amount) / loanBefore.amount)
        //   and loanAfter.amount == loanBefore.amount - min(repaid_, loanBefore.amount)
        //   and loanAfter.collateral == loanBefore.collateral - decollateralizedReturned
        //   and debt balances moved: caller decreased by min(repaid, loanBefore.amount) and either contract or lender increased accordingly.

        if (!couldReadBefore) {
            // No loan existed before; repay must revert (cannot succeed)
            assert(reverted);
            return;
        }

        if (reverted) {
            // loan must be unchanged and balances must be unchanged
            assert(couldReadAfter);
            assert(loanAfter.amount == loanBefore.amount);
            assert(loanAfter.collateral == loanBefore.collateral);
            assert(debtBalCallerAfter == debtBalCallerBefore);
            assert(debtBalContractAfter == debtBalContractBefore);
            assert(collBalContractAfter == collBalContractBefore);
            assert(collBalOwnerAfter == collBalOwnerBefore);
            return;
        }

        // Success case: check arithmetic relation and state changes
        uint256 repaidEffective = repaid_;
        if (repaidEffective > loanBefore.amount) repaidEffective = loanBefore.amount;

        // expected decollateralized = floor(loanBefore.collateral * repaidEffective / loanBefore.amount)
        uint256 expectedDecollateralized = 0;
        if (loanBefore.amount != 0) {
            expectedDecollateralized = (loanBefore.collateral * repaidEffective) / loanBefore.amount;
        }

        // Assertions relating returned value and loan state
        assert(decollateralizedReturned == expectedDecollateralized);
        assert(couldReadAfter);
        assert(loanAfter.amount + repaidEffective == loanBefore.amount);
        assert(loanAfter.collateral + expectedDecollateralized == loanBefore.collateral);

        // Debt token movement: caller balance decreased by repaidEffective
        assert(debtBalCallerAfter + repaidEffective == debtBalCallerBefore);
        // Either contract received the repaid tokens (if repayDirect == false then unclaimed added but tokens stay at contract)
        // or lender received them (repayDirect == true). We can't read repayDirect directly in all cases, but we can assert total debt token balance between contract and lender increased by repaidEffective.
        uint256 lenderDebtBefore = debtToken.balanceOf(loanBefore.lender);
        uint256 lenderDebtAfter = debtToken.balanceOf(loanBefore.lender);
        assert(debtBalContractAfter + lenderDebtAfter == debtBalContractBefore + lenderDebtBefore + repaidEffective);
    }

    // receive to accept any token-less ETH if needed
    receive() external payable {}
}

