    // params: loanID, repaid amount
    function run(uint256 loanID, uint256 repaid) public payable {
        require(true);

        // Observe loan state before call via public getter
        // getLoan returns the Loan struct; we can read its fields
        C.Loan memory loanBefore = c.getLoan(loanID);

        bool didRevert = false;
        uint256 decollateralizedReturned = 0;
        // Attempt to call repayLoan; capture revert
        try c.repayLoan(loanID, repaid) returns (uint256 dec) {
            didRevert = false;
            decollateralizedReturned = dec;
        } catch {
            didRevert = true;
        }

        // Read loan after (if exists). For simplicity, if loans array shorter, getLoan will revert;
        // accessing getLoan in assert only when loan existed before or after could revert — avoid calling it.
        // Instead we assert properties obtainable from observed before-state, params, and return/revert.

        // General rule:
        // If call succeeded (not reverted):
        //  - returned decollateralized equals floor(loanBefore.collateral * min(repaid, loanBefore.amount) / loanBefore.amount)
        //  - returned decollateralized > 0
        // If call reverted: nothing required about return value.

        // Protect division by zero: if loanBefore.amount == 0 then contract would have reverted when repaying (no loan),
        // so when call succeeded we require loanBefore.amount != 0.

        if (!didRevert) {
            // compute expected decollateralized
            uint256 effectiveRepaid = repaid;
            if (effectiveRepaid > loanBefore.amount) effectiveRepaid = loanBefore.amount;
            // avoid division by zero
            assert(loanBefore.amount != 0);
            uint256 expected = (loanBefore.collateral * effectiveRepaid) / loanBefore.amount;
            // returned must equal expected and be > 0
            assert(decollateralizedReturned == expected && decollateralizedReturned > 0);
        } else {
            // If reverted, we assert nothing about returned value; but for usefulness, ensure that
            // only possible reason when loan existed and repaid > 0 would be if loan was expired (Default)
            // We cannot reliably determine block.timestamp here, so we make no extra requirement.
            assert(didRevert == true);
        }
    }

    receive() external payable {}
}

