    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral cannot be zero");

        // Read current number of requests by probing indexes until one reverts would be expensive; instead
        // we use a safe approach: try to read request at index 0..N until a call reverts is not allowed in assertion.
