        ERC20 coll = c.collateral();
        uint256 balBefore = coll.balanceOf(address(c));

        // Call requestLoan from this contract (msg.sender for c will be this test contract).
        bool reverted;
        try c.requestLoan(amount, interest, loanToCollateral, duration) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, then a new request was appended and should be active.
        // We can read the last request via getRequest(reqID) where reqID = requests.length-1.
        // But we don't have direct access to requests.length; however requestLoan returns reqID.
        // Because we used try/catch we couldn't capture the return value; instead we infer that
        // when not reverted the requests array grew by 1 and the newly pushed request is active.
        // To make a general observable assertion: if not reverted then there exists at least one
        // active request (isActive returns true for some index). We'll check that the most
        // recently appended request (we find by scanning from 0 up to a reasonable bound)
        // is active and that the contract balance increased by collateralFor(amount,loanToCollateral).

