        // deploys a fresh c, the number of requests is small; this keeps the assertion expressible.
        bool foundActive = false;
        for (uint256 i = 0; i < 20; i++) {
            // getRequest is a view that returns the struct; use isActive public instead to avoid
            // dealing with struct packing. We call isActive(i).
            try c.isActive(i) returns (bool active) {
                if (active) { foundActive = true; break; }
            } catch {
                // out-of-bounds will revert; stop scanning
                break;
            }
        }

        assert(reverted || (foundActive && balAfter >= balBefore + expectedCollat));
    }

