    // params: amount, interest, loanToCollateral, duration
    // We require that the caller (this contract) has previously approved collateral transfer out-of-band
    // The test invokes requestLoan and then asserts the properties about the new request and collateral balance change
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral must be nonzero");

        // Read before-state
        uint256 beforeLen = c.requestsLength();
        // observe contract collateral token and this contract's balance of that token via ERC20.balanceOf
        // collateral() is public view returning ERC20
        ERC20 coll = c.collateral();
        uint256 beforeCollBalance = coll.balanceOf(address(c));

        bool reverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-state observations
        uint256 afterLen = c.requestsLength();
        // If the call reverted then requests length must be unchanged and contract collateral balance unchanged
        // If the call succeeded then length increased by 1, and the newest request matches inputs and is active,
        // and contract collateral balance increased by collateralFor(amount_, loanToCollateral_)

        if (reverted) {
            assert(afterLen == beforeLen && coll.balanceOf(address(c)) == beforeCollBalance);
        } else {
            // read the newly created request
            uint256 newIdx = afterLen - 1;
            C.Request memory req = c.getRequest(newIdx);
            uint256 expectedColl = c.collateralFor(amount_, loanToCollateral_);
            // general rule asserting all together
            assert(
                afterLen == beforeLen + 1
                && req.amount == amount_
                && req.interest == interest_
                && req.loanToCollateral == loanToCollateral_
                && req.duration == duration_
                && req.active == true
                && coll.balanceOf(address(c)) >= beforeCollBalance + expectedColl
            );
        }
    }

    // helpers to expose array length via public call (uses C's public Requests array auto-generated getter isn't length-exposing, so we rely on request indices via getRequest and requestsLength)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount, interest, loanToCollateral, duration
    // require nonzero loanToCollateral to avoid division-by-zero behavior in collateralFor
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral must be nonzero");

        // Observe before-state: length of requests by probing until out-of-bounds
        uint256 beforeLen = 0;
        // Try to find length by incrementally calling getRequest until it reverts
        // We must bound loop to avoid excessive gas; use a reasonable cap
        uint256 cap = 50;
        for (uint256 i = 0; i < cap; i++) {
            // attempt to read request i
            bool ok = true;
            try c.getRequest(i) returns (C.Request memory) {
                // exists
            } catch {
                ok = false;
            }
            if (!ok) { beforeLen = i; break; }
            // if reached cap-1 and still exists, set beforeLen = cap
            if (i == cap - 1) { beforeLen = cap; }
        }

        // read collateral token and contract collateral balance before
        ERC20 coll = c.collateral();
        uint256 beforeCollBalance = coll.balanceOf(address(c));

        bool reverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-state length same way (with same cap)
        uint256 afterLen = 0;
        for (uint256 i = 0; i < cap; i++) {
            bool ok = true;
            try c.getRequest(i) returns (C.Request memory) {
            } catch {
                ok = false;
            }
            if (!ok) { afterLen = i; break; }
            if (i == cap - 1) { afterLen = cap; }
        }

        uint256 afterCollBalance = coll.balanceOf(address(c));

        // If reverted: length and collateral balance must be unchanged.
        // If succeeded: length increased by exactly 1 (unless cap prevents detection), newest request matches inputs and active,
        // and contract collateral balance increased by collateralFor(amount_, loanToCollateral_).
        if (reverted) {
            assert(afterLen == beforeLen && afterCollBalance == beforeCollBalance);
        } else {
            // when beforeLen == cap we cannot be sure about exact increment due to cap; require that afterLen >= beforeLen + 1 in that case
            uint256 expectedColl = c.collateralFor(amount_, loanToCollateral_);
            if (beforeLen < cap) {
                // read the newly created request
                C.Request memory req = c.getRequest(beforeLen);
                assert(
                    afterLen == beforeLen + 1
                    && req.amount == amount_
                    && req.interest == interest_
                    && req.loanToCollateral == loanToCollateral_
                    && req.duration == duration_
                    && req.active == true
                    && afterCollBalance >= beforeCollBalance + expectedColl
                );
            } else {
                // best-effort: ensure collateral increased and some request at index cap-1 exists (we observed it before)
                // since we couldn't determine precise length, assert at least collateral change and that afterLen >= beforeLen
                assert(afterCollBalance >= beforeCollBalance + expectedColl && afterLen >= beforeLen);
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We avoid loanToCollateral_ == 0 to prevent division-by-zero in collateralFor
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral must be nonzero");

        ERC20 coll = c.collateral();
        uint256 beforeCollBalance = coll.balanceOf(address(c));

        bool reverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
